answer.src:
fun transfer(from: Account, to: Account, amount: Long) {
    val (first, second) = if (from.id < to.id) from to to else to to from   // one global order: by id
    synchronized(first) {
        synchronized(second) {
            from.balance -= amount
            to.balance += amount
        }
    }
}

// mutual exclusion -> no lock at all: CAS on one word (AtomicLong), only for single-word updates
// hold and wait    -> take every lock at once, under one global lock
// no preemption    -> tryLock(timeout) the second, release the first, random back-off, retry
// circular wait    -> lock in a global order (above)
